import sys

MOD = 998244353

def factor(x):
    result = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            result[d] = result.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        result[x] = result.get(x, 0) + 1
    return result

values = list(map(int, sys.stdin.buffer.read().split()))
n = values[0]
factors = [factor(x) for x in values[1:]]
primes = set()
for f in factors:
    primes.update(f)

answer = 1
for p in primes:
    steps = [f.get(p, 0) for f in factors]
    bound = sum(steps)

    powers = [1] * (bound + 1)
    for h in range(1, bound + 1):
        powers[h] = powers[h - 1] * p % MOD

    # no[h]: paths currently at height h which have not yet visited 0
    # hit[h]: paths currently at height h which have visited 0
    hit = [0] * (bound + 1)
    no = [0] * (bound + 1)
    hit[0] = 1
    for h in range(1, bound + 1):
        no[h] = powers[h]  # choose the initial height h

    for step in steps:
        next_hit = [0] * (bound + 1)
        next_no = [0] * (bound + 1)
        for height in range(bound + 1):
            if step == 0:
                destinations = (height,)
            else:
                destinations = (height + step, height - step)
            for dest in destinations:
                if dest < 0 or dest > bound:
                    continue
                weight = powers[dest]
                if hit[height]:
                    next_hit[dest] = (next_hit[dest] + hit[height] * weight) % MOD
                if no[height]:
                    if dest == 0:
                        next_hit[dest] = (next_hit[dest] + no[height]) % MOD
                    else:
                        next_no[dest] = (next_no[dest] + no[height] * weight) % MOD
        hit, no = next_hit, next_no

    answer = answer * sum(hit) % MOD

print(answer)

