MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for v in range(p, mx + 1, p):
                phi[v] -= phi[v] // p

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, mx + 1, p):
                if spf[v] == v:
                    spf[v] = p

    cache = {}
    weights = [0] * (mx + 1)
    ans = 0
    power = 1
    out = []

    for x in a:
        ds = cache.get(x)
        if ds is None:
            factors = []
            t = x
            while t > 1:
                p = spf[t]
                e = 0
                while t % p == 0:
                    t //= p
                    e += 1
                factors.append((p, e))
            ds = [1]
            for p, e in factors:
                base = ds[:]
                mul = 1
                for _ in range(e):
                    mul *= p
                    ds.extend(d * mul for d in base)
            cache[x] = ds

        s = 0
        for d in ds:
            s += phi[d] * weights[d]
        s %= MOD
        ans = (2 * ans + s) % MOD
        out.append(str(ans))

        for d in ds:
            v = weights[d] + power
            if v >= MOD:
                v -= MOD
            weights[d] = v
        power = (power * 2) % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

