from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        top = second = top_count = 0
        top_id = -1
        base = 0
        gains = [0] * m

        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > top:
                    second = top
                    top = a
                    top_count = 1
                    top_id = idx
                elif a == top:
                    top_count += 1
                elif a > second:
                    second = a

            base += r - top
            if top_count == 1:
                gains[top_id] += top - second

        return base + max(gains)

