class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle gives all needed binomial coefficients.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # For a number with c set bits, the first operation gives c.
        # Thus its reduction count is one plus the reduction count of c.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            value = c
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1
            good[c] = steps + 1 <= k

        answer = 0
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Make this bit 0; freely choose the suffix to obtain each
                # possible total number of set bits.
                for total_ones in range(1, n + 1):
                    if good[total_ones]:
                        needed = total_ones - ones_so_far
                        if 0 <= needed <= remaining:
                            answer += comb[remaining][needed]
                ones_so_far += 1

        return answer % MOD

