class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Pascal table for combinations up to n
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

        good = [False] * (n + 1)
        for c in range(1, n + 1):
            v = c
            steps = 0
            while v > 1:
                v = v.bit_count()
                steps += 1
            good[c] = steps + 1 <= k

        ans = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for c in range(1, n + 1):
                    if good[c]:
                        need = c - ones
                        if 0 <= need <= rem:
                            ans += C[rem][need]
                ones += 1
        return ans % MOD

