    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    pq = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(pq, (0, i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                heapq.heappush(pq, (1, i, j))

    while pq:
        length, u, v = heapq.heappop(pq)
        if dist[u][v] != length:
            continue
        new_length = length + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
