import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]
    U = data[2::2]
    D = data[3::2]
    sums = [u + d for u, d in zip(U, D)]

    def feasible(h):
        lo = max(0, h - D[0])
        hi = min(U[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            next_lo = max(0, h - D[i])
            next_hi = min(U[i], h)
            lo = max(next_lo, lo - x)
            hi = min(next_hi, hi + x)
            if lo > hi:
                return False
        return True

    left, right = 0, min(sums) + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(sum(sums) - n * left)

if __name__ == '__main__':
    main()

