lo, hi = 0, 1_000_001
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    # N = d * (3*y^2 + 3*d*y + d^2)
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
        break
