from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order: SE, SW, NW, NE
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        # straight[p][d][r][c]: consecutive cells starting at (r,c)
        # matching the alternating sequence beginning with 2 (p=0) or 0 (p=1).
        straight = [[[[0] * m for _ in range(n)] for _ in range(4)] for _ in range(2)]

        for p in range(2):
            first = 2 if p == 0 else 0
            for d, (dr, dc) in enumerate(dirs):
                rows = range(n - 1, -1, -1) if dr == 1 else range(n)
                cols = range(m - 1, -1, -1) if dc == 1 else range(m)
                arr = straight[p][d]
                for r in rows:
                    for c in cols:
                        if grid[r][c] == first:
                            nr, nc = r + dr, c + dc
                            arr[r][c] = 1
                            if 0 <= nr < n and 0 <= nc < m:
                                arr[r][c] += straight[1 - p][d][nr][nc]

        # With a turn remaining, follow the current direction or turn clockwise.
        # Recursion only moves diagonally, so its depth is at most min(n,m).
        from functools import lru_cache

        @lru_cache(None)
        def best(r: int, c: int, d: int, p: int) -> int:
            dr, dc = dirs[d]
            nr, nc = r + dr, c + dc
            first = 2 if p == 0 else 0
            if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] != first:
                return 0

            # Count the next cell, then continue straight or turn clockwise there.
            return 1 + max(
                best(nr, nc, d, 1 - p),
                straight[1 - p][(d + 1) % 4][nr][nc]
            )

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d in range(4):
                        answer = max(answer, 1 + best(r, c, d, 0))
        return answer

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2

        def completions(o: int, e: int, start_parity: int) -> int:
            """Count arrangements of remaining values, requiring start parity (1 odd, 0 even)."""
            length = o + e
            odd_slots = (length + 1) // 2 if start_parity == 1 else length // 2
            even_slots = length - odd_slots
            if o != odd_slots or e != even_slots:
                return 0
            # Values of each parity can be assigned to their slots independently.
            from math import factorial
            return factorial(o) * factorial(e)

        # Reject an out-of-range rank before constructing the answer.
        total = 0
        if n:
            total += odds * completions(odds - 1, evens, 0)
            total += evens * completions(odds, evens - 1, 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        answer = []
        last_parity = None
        while remaining:
            chosen = None
            for x in remaining:
                parity = x % 2
                if last_parity is not None and parity == last_parity:
                    continue
                o = sum(1 for y in remaining if y % 2 == 1) - (parity == 1)
                e = sum(1 for y in remaining if y % 2 == 0) - (parity == 0)
                left = len(remaining) - 1
                if left == 0:
                    ways = 1
                else:
                    ways = completions(o, e, 1 - parity)
                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    last_parity = parity
                    answer.append(x)
                    remaining.remove(x)
                    break
            if chosen is None:
                return []
        return answer

