class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Each independent digit contributes to both mirrored places.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # suffix[i] is a bitset of residues achievable by variables i onward.
        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue 0
        for i in range(m - 1, -1, -1):
            low = 1 if i == 0 else 0
            possible = 0
            for digit in range(low, 10):
                shift = digit * coeff[i] % k
                bits = suffix[i + 1]
                if shift:
                    bits = ((bits << shift) | (bits >> (k - shift))) & full
                possible |= bits
            suffix[i] = possible

        # Greedily maximize the left half while keeping a feasible suffix.
        left = []
        prefix = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                needed = (-(prefix + digit * c)) % k
                if (suffix[i + 1] >> needed) & 1:
                    left.append(str(digit))
                    prefix = (prefix + digit * c) % k
                    break

        left = ''.join(left)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

