from functools import lru_cache
import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    values = values[:n] + values[n:n + m] + values[n + m:n + m + l]
    k = len(values)
    full = (1 << k) - 1

    @lru_cache(None)
    def winning(takahashi, aoki, turn):
        hand = takahashi if turn == 0 else aoki
        if hand == 0:
            return False

        table = full ^ (takahashi | aoki)
        cards = hand
        while cards:
            played = cards & -cards
            cards -= played
            value = values[played.bit_length() - 1]
            own_after_play = hand ^ played
            table_after_play = table | played

            # The player may choose not to take a card.
            if turn == 0:
                if not winning(own_after_play, aoki, 1):
                    return True
            else:
                if not winning(takahashi, own_after_play, 0):
                    return True

            # Or take any lower-valued card from the table.
            eligible = table_after_play
            while eligible:
                taken = eligible & -eligible
                eligible -= taken
                if values[taken.bit_length() - 1] < value:
                    new_hand = own_after_play | taken
                    if turn == 0:
                        if not winning(new_hand, aoki, 1):
                            return True
                    else:
                        if not winning(takahashi, new_hand, 0):
                            return True
        return False

    initial_takahashi = (1 << n) - 1
    initial_aoki = ((1 << m) - 1) << n
    print("Takahashi" if winning(initial_takahashi, initial_aoki, 0) else "Aoki")

