from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a, b, c = (occurrences(t) for t in parts)
        best = n + 1
        for x in a:
            i = bisect_left(b, x + len(parts[0]))
            if i == len(b):
                continue
            y = b[i]
            j = bisect_left(c, y + len(parts[1]))
            if j == len(c):
                continue
            z = c[j]
            best = min(best, z + len(parts[2]) - x)
        return best if best <= n else -1

