        root_value = 0
        size = len(component)
        for bit in range(30):
            ones = sum((value[u] >> bit) & 1 for u in component)
            if ones * 2 > size:
                root_value |= 1 << bit
        for u in component:
            answer[u] = value[u] ^ root_value

    print(*answer)

