import sys

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out = []
    p = 1

    for _ in range(t):
        n = int(data[p])
        a = data[p + 1]
        b = data[p + 2]
        p += 3

        src = [i for i, c in enumerate(a) if c == 49]
        dst = [i for i, c in enumerate(b) if c == 49]

        if len(src) < len(dst):
            out.append("-1")
            continue

        def feasible(d):
            j = 0
            for x in src:
                while j < len(dst) and dst[j] < x - d:
                    j += 1
                if j == len(dst) or dst[j] > x + d:
                    return False
                # Keep assigning to the current target when possible;
                # otherwise advance to the next one.
                if dst[j] < x - d:
                    return False
                if j + 1 < len(dst) and dst[j + 1] <= x + d and dst[j] < x - d:
                    j += 1
            return j == len(dst) - 1

        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        out.append(str(lo))

    print("\n".join(out))

