class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, with children visited by increasing id.
        order = []
        stack = [(0, 0)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                order.append(v)
            else:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))

        pos = [0] * n
        size = [1] * n
        for i, v in enumerate(order):
            pos[v] = i
            if parent[v] != -1:
                size[parent[v]] += size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii for odd and even length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            end = pos[v]
            length = size[v]
            start = end - length + 1
            if length & 1:
                answer[v] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[v] = even[(start + end + 1) // 2] >= length // 2
        return answer

