import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        low = 0 if digits == 1 else 10 ** (digits - 1)
        high = 10 ** digits - 1

        # The starting value is included in the total cost.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            text = str(value)
            for i, char in enumerate(text):
                digit = ord(char) - 48
                place = 10 ** (digits - 1 - i)

                if digit < 9:
                    nxt = value + place
                    if low <= nxt <= high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

                if digit > 0:
                    nxt = value - place
                    if low <= nxt <= high and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

