from typing import List
class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n=len(nums)
        ans=0
        # z for original: whether first piece is prefix of second
        z=[0]*n
        l=r=0
        for i in range(1,n):
            if i<r: z[i]=min(r-i,z[i-l])
            while i+z[i]<n and nums[z[i]]==nums[i+z[i]]: z[i]+=1
            if i+z[i]>r: l,r=i,i+z[i]
        for i in range(1,n-1):
            m=n-i
            if z[i]>=i:
                ans += m-1
            # z-function of nums[i:]
            a=nums[i:]
            q=[0]*m
            l=r=0
            for k in range(1,m):
                if k<r: q[k]=min(r-k,q[k-l])
                while k+q[k]<m and a[q[k]]==a[k+q[k]]: q[k]+=1
                if k+q[k]>r: l,r=k,k+q[k]
            for d in range(1,m):
                if q[d]>=d: ans+=1
        return ans

