class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        can_remove = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            ndp = [neg] * (m + 1)
            removable = i in can_remove
            for j in range(m + 1):
                if dp[j] == neg:
                    continue
                # Keep this character unused.
                ndp[j] = max(ndp[j], dp[j])
                if removable:
                    ndp[j] = max(ndp[j], dp[j] + 1)
                if j < m and ch == pattern[j]:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])
            dp = ndp
        return dp[m]

