from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse reversed edges from 0 to determine which nodes can reach 0.
        rev = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            rev[b].append((a, w))
            weights.append(w)

        weights = sorted(set(weights))

        def possible(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        count += 1
                        stack.append(u)
            return count == n

        if not possible(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

