class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        inf = 10**30
        # dp[a][b]: minimum cost through the current pair, whose
        # left and right houses have colors a and b respectively.
        dp = [[inf] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, n // 2):
            r = n - 1 - i
            ndp = [[inf] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    pair_cost = cost[i][a] + cost[r][b]
                    for x in range(3):
                        for y in range(3):
                            if x != y and a != x and b != y:
                                ndp[a][b] = min(ndp[a][b], dp[x][y] + pair_cost)
            dp = ndp

        return min(min(row) for row in dp)

