class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(point) for point in points}
        xs = sorted({x for x, y in point_set})
        ys = sorted({y for x, y in point_set})
        answer = -1

        for i, x1 in enumerate(xs):
            for x2 in xs[i + 1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j + 1:]:
                        corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                        if not corners.issubset(point_set):
                            continue
                        if any(
                            x1 <= x <= x2 and y1 <= y <= y2
                            for x, y in point_set - corners
                        ):
                            continue
                        answer = max(answer, (x2 - x1) * (y2 - y1))

        return answer

